SELECT g.account,a.account_name,a.root_type,a.account_type,SUM(g.debit) AS debit,SUM(g.credit) AS credit,SUM(g.debit-g.credit) AS balance FROM "tabGL Entry" g JOIN "tabAccount" a ON a.name=g.account WHERE (%(company)s='' OR g.company=%(company)s) AND (%(from_date)s='' OR g.posting_date>=%(from_date)s) AND (%(to_date)s='' OR g.posting_date<=%(to_date)s) GROUP BY g.account,a.account_name,a.root_type,a.account_type HAVING ABS(SUM(g.debit))+ABS(SUM(g.credit))>0 ORDER BY a.account_number,g.account
